from dataclasses import dataclass
from datetime import date


@dataclass
class Kitap:
    id: int
    ad: str
    yazar: str


@dataclass
class Uye:
    id: int
    ad: str
    tur: str = "standart"  # "standart" ya da "ogrenci"


@dataclass
class Odunc:
    kitap_id: int
    uye_id: int
    alinma: date
    iade: date | None = None
    ceza: float = 0.0

from .modeller import Odunc
from datetime import date


class KutuphaneServisi:
    def __init__(self):
        self.kitaplar = {}
        self.uyeler = {}
        self.kayitlar = []

    def kitap_ekle(self, kitap):
        self.kitaplar[kitap.id] = kitap

    def uye_ekle(self, uye):
        self.uyeler[uye.id] = uye

    def _aktif(self, kitap_id):
        return next((k for k in self.kayitlar if k.kitap_id == kitap_id and k.iade is None), None)

    def odunc_ver(self, kitap_id, uye_id, tarih):
        """Kitabı üyeye verir. Kitap/üye yoksa ya da kitap zaten ödünçteyse ValueError."""
        if kitap_id not in self.kitaplar or uye_id not in self.uyeler:
            raise ValueError("kitap ya da üye bulunamadı")
        if self._aktif(kitap_id):
            raise ValueError("kitap zaten ödünçte")

        # Check book limit for the member
        uye = self.uyeler[uye_id]
        active_books = len([k for k in self.kayitlar if k.uye_id == uye_id and k.iade is None])
        max_books = 5 if uye.tur == "ogrenci" else 3

        if active_books >= max_books:
            raise ValueError("üye için maksimum kitap sayısı aşıldı")

        kayit = Odunc(kitap_id, uye_id, tarih)
        self.kayitlar.append(kayit)
        return kayit

    def iade_al(self, kitap_id, tarih):
        """Kitabın iadesini alır ve ödünç kaydını döndürür. Kitap ödünçte değilse ValueError."""
        kayit = self._aktif(kitap_id)
        if kayit is None:
            raise ValueError("kitap ödünçte değil")

        # Calculate penalty
        duration_days = (tarih - kayit.alinma).days
        if duration_days > 14:
            overdue_days = duration_days - 14
            ceza = 0.0

            # First 7 days: 2.50 TL per day
            if overdue_days <= 7:
                ceza = overdue_days * 2.50
            else:
                # First 7 days: 2.50 TL per day (35 TL)
                # Remaining days: 5.00 TL per day
                ceza = 7 * 2.50 + (overdue_days - 7) * 5.00

            # Cap at 150 TL
            if ceza > 150:
                ceza = 150

            # Apply 50% discount for students
            uye = self.uyeler[kayit.uye_id]
            if uye.tur == "ogrenci":
                ceza *= 0.5

            # Round to 2 decimal places
            ceza = round(ceza, 2)

            kayit.ceza = ceza

        kayit.iade = tarih
        return kayit

    def oduncteki_kitaplar(self, uye_id):
        return sorted(k.kitap_id for k in self.kayitlar if k.uye_id == uye_id and k.iade is None)

